-- --- Institutions (22) ------------------------------------------------------------
--
-- Every campus listed in `colleges.md`, one row each. Bohol has 28 HEIs by CHED RO VII's count;
-- these 22 campuses are the ones the source document enumerates, and the rest are absent
-- rather than guessed at.
--
-- The list spans all three sectors the province has, which matters because the tier an
-- institution sits in changes who can realistically attend it: the state university (BISU, six
-- campuses), the private universities and colleges (UB, HNU, BIT ×4, Mater Dei, Bohol Northern
-- Star, PMI, Cristal ×2), and the LUC tier funded by a municipal or city ordinance (Buenavista,
-- Trinidad, Batuan, Talibon Polytechnic, Tagbilaran City College).
--
-- `map_link` is the institution's own Google Maps share link, copied from `colleges.md`. Where
-- the source document has no link (BIT Carmen), it falls back to a Maps *search* URL built from
-- the campus name and town — an honest "find this place". What is never emitted is a
-- `/maps/place/…` pin this seed invented, because a pin encodes a surveyed coordinate and
-- fabricating one would be seeding a claim rather than a fact.

INSERT OR IGNORE INTO colleges (id, name, description, status, region_id, province_id, town_id, map_link, created_at, updated_at) VALUES
