('711d227b-0fa8-5f44-9546-3529b99d2da8', 'Philippine Maritime Institute - Bohol', 'The Bohol campus of the Philippine Maritime Institute, a maritime-only institution offering marine transportation and marine engineering. Both are MARINA/STCW credential paths rather than PRC ones.', 'active', (SELECT id FROM regions WHERE name = 'Region VII (Central Visayas)' COLLATE NOCASE AND deleted_at IS NULL), (SELECT p.id FROM provinces p JOIN regions r ON r.id = p.region_id WHERE p.name = 'Bohol' COLLATE NOCASE AND p.deleted_at IS NULL AND r.name = 'Region VII (Central Visayas)' COLLATE NOCASE AND r.deleted_at IS NULL), (SELECT t.id FROM towns t JOIN provinces p ON p.id = t.province_id JOIN regions r ON r.id = p.region_id WHERE t.name = 'Tagbilaran City' COLLATE NOCASE AND t.deleted_at IS NULL AND p.name = 'Bohol' COLLATE NOCASE AND p.deleted_at IS NULL AND r.name = 'Region VII (Central Visayas)' COLLATE NOCASE AND r.deleted_at IS NULL), 'https://maps.app.goo.gl/YpY9SCGRGpZhFog89', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
