('9eaa43fe-7e6c-5006-8f6b-df43abc4621d', 'Cristal e-College - Panglao Campus', 'The Panglao campus of Cristal e-College, on the island, pairing tourism and information technology with the maritime programmes the Tagbilaran campus does not offer.', 'active', (SELECT id FROM regions WHERE name = 'Region VII (Central Visayas)' COLLATE NOCASE AND deleted_at IS NULL), (SELECT p.id FROM provinces p JOIN regions r ON r.id = p.region_id WHERE p.name = 'Bohol' COLLATE NOCASE AND p.deleted_at IS NULL AND r.name = 'Region VII (Central Visayas)' COLLATE NOCASE AND r.deleted_at IS NULL), (SELECT t.id FROM towns t JOIN provinces p ON p.id = t.province_id JOIN regions r ON r.id = p.region_id WHERE t.name = 'Panglao' COLLATE NOCASE AND t.deleted_at IS NULL AND p.name = 'Bohol' COLLATE NOCASE AND p.deleted_at IS NULL AND r.name = 'Region VII (Central Visayas)' COLLATE NOCASE AND r.deleted_at IS NULL), 'https://maps.app.goo.gl/gNd9dQvxqcRDHzVdA', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
