('595549c4-e1c7-5c70-8916-3e17e51708f2', 'Trinidad Municipal College', 'The municipal college of Trinidad, offering business administration, public administration and elementary education.', 'active', (SELECT id FROM regions WHERE name = 'Region VII (Central Visayas)' COLLATE NOCASE AND deleted_at IS NULL), (SELECT p.id FROM provinces p JOIN regions r ON r.id = p.region_id WHERE p.name = 'Bohol' COLLATE NOCASE AND p.deleted_at IS NULL AND r.name = 'Region VII (Central Visayas)' COLLATE NOCASE AND r.deleted_at IS NULL), (SELECT t.id FROM towns t JOIN provinces p ON p.id = t.province_id JOIN regions r ON r.id = p.region_id WHERE t.name = 'Trinidad' COLLATE NOCASE AND t.deleted_at IS NULL AND p.name = 'Bohol' COLLATE NOCASE AND p.deleted_at IS NULL AND r.name = 'Region VII (Central Visayas)' COLLATE NOCASE AND r.deleted_at IS NULL), 'https://maps.app.goo.gl/EC8zB2SpL7woPMdb9', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('744226f4-5971-545c-9d4a-1c659bb32884', 'Batuan College', 'The municipal college of Batuan, interior Bohol, offering elementary education, secondary education and business administration.', 'active', (SELECT id FROM regions WHERE name = 'Region VII (Central Visayas)' COLLATE NOCASE AND deleted_at IS NULL), (SELECT p.id FROM provinces p JOIN regions r ON r.id = p.region_id WHERE p.name = 'Bohol' COLLATE NOCASE AND p.deleted_at IS NULL AND r.name = 'Region VII (Central Visayas)' COLLATE NOCASE AND r.deleted_at IS NULL), (SELECT t.id FROM towns t JOIN provinces p ON p.id = t.province_id JOIN regions r ON r.id = p.region_id WHERE t.name = 'Batuan' COLLATE NOCASE AND t.deleted_at IS NULL AND p.name = 'Bohol' COLLATE NOCASE AND p.deleted_at IS NULL AND r.name = 'Region VII (Central Visayas)' COLLATE NOCASE AND r.deleted_at IS NULL), 'https://maps.app.goo.gl/kzzhSChu39ga17j98', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('b64ae935-3ae7-5d6d-a91e-d44ba9b65f4b', 'Talibon Polytechnic College', 'The polytechnic college of Talibon, and the broadest LUC offering in the province: agriculture, accounting information systems, information systems, criminology, political science and English language.', 'active', (SELECT id FROM regions WHERE name = 'Region VII (Central Visayas)' COLLATE NOCASE AND deleted_at IS NULL), (SELECT p.id FROM provinces p JOIN regions r ON r.id = p.region_id WHERE p.name = 'Bohol' COLLATE NOCASE AND p.deleted_at IS NULL AND r.name = 'Region VII (Central Visayas)' COLLATE NOCASE AND r.deleted_at IS NULL), (SELECT t.id FROM towns t JOIN provinces p ON p.id = t.province_id JOIN regions r ON r.id = p.region_id WHERE t.name = 'Talibon' COLLATE NOCASE AND t.deleted_at IS NULL AND p.name = 'Bohol' COLLATE NOCASE AND p.deleted_at IS NULL AND r.name = 'Region VII (Central Visayas)' COLLATE NOCASE AND r.deleted_at IS NULL), 'https://maps.app.goo.gl/5iguk1Mf4FmCZ8aL9', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
