-- --- Careers (108) ------------------------------------------------------------------
--
-- `employment_outlook_id` references the lookup seeded by migration 0013
-- (e0000001…4 = Low / Moderate / High / Emerging).
--
-- The count matters. TOP_N in src/lib/recommendation.ts is 10, so a catalog holding exactly ten
-- careers hands every student the entire catalog reordered — two students with opposite RIASEC
-- profiles receive identical lists. That is audit C1, and it is the reason this catalog is
-- 108 careers rather than the 10 the source document's summary table enumerates.
--
-- Every regulated profession's description names the statute and the PRC examination standing
-- between graduation and practice. The source is explicit that an automated system must never
-- let a degree read as a licence, and the description is where a student reads that.

INSERT OR IGNORE INTO careers (id, title, description, salary_min, salary_max, employment_outlook_id, typical_riasec_code, status, created_at, updated_at) VALUES
('174282a0-24a2-5584-bb25-c0feca9d1f40', 'Software Developer', 'Designs, builds and maintains software systems, from backend services to full-stack web applications. Not a regulated profession — employers hire on portfolio and industry certifications (AWS, Oracle, Microsoft) rather than a PRC licence.', 30000, 140000, 'e0000003-0000-4000-8000-000000000003', 'IEC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('5302d10e-a6c0-58e5-bc09-3fed698ba0bf', 'Data Scientist', 'Builds statistical and machine-learning models to answer business and research questions. Non-regulated; machine-learning and cloud certifications are the usual credential. Common in Cebu analytics firms, FinTech and research units.', 55000, 180000, 'e0000004-0000-4000-8000-000000000004', 'IRC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('57a4104a-dd45-5e31-b628-dd47cd023343', 'Data Analyst', 'Turns operational data into decisions using statistics, SQL and visualisation. Non-regulated. A common first analytics role in the Cebu IT-BPO sector.', 28000, 95000, 'e0000003-0000-4000-8000-000000000003', 'ICE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('aaec48a7-9436-5dde-a940-4b54878268b5', 'Cybersecurity Analyst', 'Defends systems and networks against intrusion and data loss, running monitoring, incident response and vulnerability management. Non-regulated; credentialed through industry certifications.', 40000, 140000, 'e0000004-0000-4000-8000-000000000004', 'ICR', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('64caf45e-c67f-57f1-869d-dce71129bde6', 'Network Engineer', 'Designs and operates the networks an organisation runs on, including routing, switching and network security. Non-regulated, though a BS Electronics Engineering route to this role carries the PRC Electronics Engineer licence.', 30000, 100000, 'e0000002-0000-4000-8000-000000000002', 'RCI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('0da333d4-adc0-5120-b96e-8f2595a69627', 'Systems Administrator', 'Keeps servers, identity systems and infrastructure running, patched and backed up. Non-regulated; vendor certifications are the usual credential.', 25000, 90000, 'e0000002-0000-4000-8000-000000000002', 'CRI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('d34c0906-b8bd-5be9-95d8-6ba48653ef2a', 'Database Administrator', 'Designs, tunes and safeguards the databases an organisation depends on, including backup and recovery. Non-regulated.', 32000, 110000, 'e0000002-0000-4000-8000-000000000002', 'CIR', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('b8aac7ca-2f67-56cb-8553-ef7be69e2e65', 'Business Systems Analyst', 'Translates business processes into system requirements and works between operations and development teams. Non-regulated; the usual route from an information systems or business computing degree.', 35000, 120000, 'e0000003-0000-4000-8000-000000000003', 'CIE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('85046b25-ac5e-579c-9c59-c9033f79fd5e', 'Quality Assurance Engineer', 'Designs and runs the test suites that decide whether software ships, both manual and automated. Non-regulated.', 25000, 95000, 'e0000003-0000-4000-8000-000000000003', 'CIR', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('fa2842c3-b217-57f4-8584-8dc3ca55ce8f', 'IT Support Specialist', 'First-line technical support for users, devices and business applications. Non-regulated; a common entry point into the Cebu IT-BPO sector.', 18000, 55000, 'e0000003-0000-4000-8000-000000000003', 'CRS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('0c209644-fed2-5777-b63b-07858e1e4811', 'UI/UX Designer', 'Researches and designs how people move through digital products, from user research to interface specification. Non-regulated; hired on portfolio.', 30000, 110000, 'e0000003-0000-4000-8000-000000000003', 'AIE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('d44b861e-ccf4-5a8d-aae3-5b97ae239773', 'Cloud Infrastructure Engineer', 'Builds and operates cloud platforms and deployment pipelines. Non-regulated; AWS, Azure and GCP certifications are the recognised credential.', 45000, 160000, 'e0000004-0000-4000-8000-000000000004', 'IEC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('6751f1e0-c250-5290-a3f7-a8d959f38d8b', 'Civil Engineer', 'Performs structural calculation, construction sign-off and public works management on buildings, roads and drainage. Regulated under RA 544: a BS Civil Engineering degree grants eligibility only, and practice requires passing the PRC Civil Engineering Licensure Examination and registering with the Board.', 28000, 110000, 'e0000003-0000-4000-8000-000000000003', 'RIC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('dc3fa955-fdf7-5c5f-b0ec-5d421ae092e6', 'Construction Project Manager', 'Runs construction projects against programme, budget and quality — scheduling, subcontractors and site coordination. Not separately licensed, but a PRC engineering or architecture licence is normally expected on public works.', 45000, 150000, 'e0000003-0000-4000-8000-000000000003', 'ERC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('696cb3c8-6934-5e61-bdbb-573468e4b7ca', 'Quantity Surveyor', 'Prepares construction cost estimates, bills of quantities and progress valuations for contractors and developers. Non-regulated in the Philippines, though it is normally staffed from engineering and architecture graduates.', 25000, 90000, 'e0000002-0000-4000-8000-000000000002', 'CRI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('35cba0e7-69b6-50e7-81c2-a80a187658e9', 'Architect', 'Produces architectural design, structural signing and urban planning consultation. Regulated under RA 9266: a BS Architecture degree is followed by two years (3,840 hours) of diversified architectural mentorship under a licensed architect, and only then the Licensure Examination for Architects.', 28000, 120000, 'e0000002-0000-4000-8000-000000000002', 'AIR', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('241e78e5-1b1d-5406-8d17-ad69a1b75f2e', 'Industrial Designer', 'Designs manufactured products — furniture, equipment, packaging and consumer goods — from concept and prototype through to production drawings. Non-regulated; hired on portfolio.', 20000, 65000, 'e0000002-0000-4000-8000-000000000002', 'AIR', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('db7a25c6-013e-5e9b-a26f-41e20ce86dcb', 'Interior Designer', 'Plans interior spaces, materials and detailing for residential and commercial fit-outs. Regulated under RA 10350 — practice requires passing the PRC Interior Design Licensure Examination.', 22000, 90000, 'e0000002-0000-4000-8000-000000000002', 'AER', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('5f40f552-c97b-5256-a4d5-977a5f06706f', 'Mechanical Engineer', 'Designs and maintains machinery, thermal systems and manufacturing plant. Regulated under RA 8495 — practice requires passing the PRC Mechanical Engineer Licensure Examination.', 28000, 110000, 'e0000003-0000-4000-8000-000000000003', 'RIC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('d4adacbd-1ee6-58de-b68c-c7efac20ca7d', 'Electrical Engineer', 'Designs power systems, machines and building electrical services. Regulated under RA 7920 — practice requires passing the PRC Electrical Engineer Licensure Examination.', 30000, 115000, 'e0000003-0000-4000-8000-000000000003', 'RIC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('b5f5755b-644c-5094-8259-6981977bed07', 'Agricultural and Biosystems Engineer', 'Designs farm machinery, irrigation and drainage systems, post-harvest facilities and agricultural processing plant. Regulated under RA 10915 — practice requires passing the PRC Agricultural and Biosystems Engineering Licensure Examination.', 22000, 65000, 'e0000002-0000-4000-8000-000000000002', 'RIE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('d177ff1b-1377-5e42-b178-45a917077ad3', 'Industrial Technologist', 'Supervises manufacturing, machine shop, welding and industrial maintenance work in plants and workshops. Not a PRC-licensed engineering title — a BS Industrial Technology graduate is not eligible for the engineering board examinations, and the credentials that advance this career are TESDA National Certificates.', 15000, 42000, 'e0000002-0000-4000-8000-000000000002', 'REC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('3bf2f237-a8a8-5fb7-b854-2cb184490669', 'Electrical Technician', 'Installs, tests and maintains building wiring, motor controls and electrical equipment to Philippine Electrical Code practice. Distinct from a licensed Electrical Engineer: the ladder here runs through the PRC Registered Master Electrician examination and TESDA certification, not the engineering board.', 14000, 38000, 'e0000002-0000-4000-8000-000000000002', 'RCI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('8055ce94-a6be-5e2c-a1f2-764143c8e13d', 'Electronics Technician', 'Services, calibrates and repairs electronic instrumentation, communications and control equipment. Not the licensed Electronics Engineer title under RA 9292 — this is the technician track, credentialled through TESDA and the PRC Electronics Technician examination.', 14000, 38000, 'e0000002-0000-4000-8000-000000000002', 'RCE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('3c165efa-4c0c-5f10-89ce-73861c1f5f12', 'Forester', 'Manages forest stands, watersheds, reforestation and agroforestry programmes for DENR, LGUs and private plantations. Regulated under RA 6239 — practice requires passing the PRC Foresters Licensure Examination.', 20000, 55000, 'e0000002-0000-4000-8000-000000000002', 'RIS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('815800e6-99f2-5f0a-ab45-2f1b600a54e1', 'Computer Engineer', 'Works at the hardware-software boundary: digital systems, embedded design and computer architecture. Non-regulated, and distinct from computer science — the curriculum is built around circuits and embedded systems rather than algorithms.', 32000, 120000, 'e0000003-0000-4000-8000-000000000003', 'IRE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('999fbf39-6318-5598-939b-ea0f39036151', 'Embedded Systems Engineer', 'Writes firmware and designs the hardware-software boundary for microcontrollers, industrial controllers and connected devices. Non-regulated; the credential is demonstrated low-level work.', 30000, 100000, 'e0000003-0000-4000-8000-000000000003', 'IRE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('6eff7fb5-3fb8-5ca5-ace6-18d959c4d107', 'Instrumentation Technician', 'Installs, calibrates and troubleshoots sensors, transmitters and process control loops in plants, utilities and food processing lines. Credentialled through TESDA National Certificates rather than a PRC board.', 18000, 48000, 'e0000002-0000-4000-8000-000000000002', 'RCE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('8c35d4f2-325d-5106-a437-1984611d93dc', 'Maintenance Engineer', 'Plans and supervises preventive and corrective maintenance for plant, building systems and production equipment. Non-regulated as a title, though supervising electrical or mechanical work at scale generally requires the corresponding PRC licence.', 25000, 75000, 'e0000002-0000-4000-8000-000000000002', 'RCS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('0978801f-19ad-5cef-8d93-6c21afe733ce', 'Renewable Energy Specialist', 'Sizes, installs and commissions solar, wind and hybrid generation and storage systems, and handles the grid-connection and net-metering paperwork. Non-regulated as a title; design sign-off on a distribution system requires a licensed Electrical Engineer.', 28000, 90000, 'e0000004-0000-4000-8000-000000000004', 'IRS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('2298a085-79f5-52f6-b515-186d7beb8a56', 'Occupational Health and Safety Officer', 'Runs workplace hazard assessment, safety training and incident investigation on sites and in plants. Required by DOLE Department Order 198-18: the role needs an accredited Safety Officer certification (SO1-SO4) earned through mandatory training on top of the degree, not the degree alone.', 18000, 60000, 'e0000003-0000-4000-8000-000000000003', 'RSC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('4f8d85c0-14dd-556c-917f-0b59cc0b4a5c', 'Marine Engineer', 'Operates and maintains shipboard machinery and propulsion systems. Regulated under the STCW Convention and RA 10635 — practice requires a MARINA/PRC Certificate of Competency following approved sea service.', 40000, 200000, 'e0000003-0000-4000-8000-000000000003', 'RCE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('fb42b828-c8cd-5cc3-95a2-354a96ef6086', 'Registered Nurse', 'Delivers direct clinical care, patient assessment and bedside nursing in hospitals and clinics. Regulated under RA 9173: a BS Nursing degree grants eligibility only, and practice requires passing the Nurse Licensure Examination and holding a PRC Certificate of Registration.', 22000, 70000, 'e0000003-0000-4000-8000-000000000003', 'SIR', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('b4bbdcec-534d-5697-b863-3c5c76d6065e', 'Pharmacist', 'Dispenses medicines and advises on pharmaceutical care in hospital, retail and industry settings. Regulated under RA 10918 — practice requires passing the PRC Pharmacist Licensure Examination.', 26000, 85000, 'e0000002-0000-4000-8000-000000000002', 'ICS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('3774ce01-0a8f-5429-8329-a41a917e360a', 'Physical Therapist', 'Rehabilitates movement and physical function after injury, surgery or illness. Regulated under RA 5680 — practice requires passing the PRC Physical Therapist Licensure Examination.', 24000, 80000, 'e0000003-0000-4000-8000-000000000003', 'SIR', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('78890e70-8595-54f0-985a-db938c6be7fc', 'Midwife', 'Provides prenatal, delivery, postnatal and newborn care in birthing homes, rural health units and hospitals. Regulated under RA 7392 — practice requires passing the PRC Midwifery Licensure Examination.', 15000, 38000, 'e0000002-0000-4000-8000-000000000002', 'SRI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('7cfb913a-f1b3-5376-bf6e-fd70e9974d25', 'Regulatory Affairs Specialist', 'Prepares product registrations, licence renewals and compliance dossiers for the Philippine FDA in pharmaceutical, food and device companies. Non-regulated as a title, but the work is defined by FDA circulars.', 25000, 75000, 'e0000002-0000-4000-8000-000000000002', 'CIE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('dc6c3812-cf6d-5ff9-801d-7fdb77fdea5a', 'Medical Sales Representative', 'Details pharmaceutical and medical products to physicians, hospitals and pharmacies. Non-regulated; earnings are substantially commission, so the range below is wider in practice than a salaried role.', 18000, 65000, 'e0000002-0000-4000-8000-000000000002', 'ESI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('81b7e7bb-9709-55ca-ab03-df0f91812ff1', 'Sports Rehabilitation Specialist', 'Manages injury prevention, conditioning and return-to-play rehabilitation for athletes and active patients. Where the work is physical therapy it requires the PRC Physical Therapist licence under RA 5680; conditioning and strength coaching do not.', 20000, 60000, 'e0000002-0000-4000-8000-000000000002', 'SRI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('43f6bc59-8edc-59d8-931c-4f174a448f28', 'Clinical Researcher', 'Coordinates clinical trials — monitoring, medical documentation and patient consent protocols — for pharmaceutical companies and research organisations. Non-regulated; Good Clinical Practice (GCP) certification is the usual credential.', 32000, 110000, 'e0000004-0000-4000-8000-000000000004', 'ISC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('d8d077e2-b2c9-5153-9fd1-298972304e07', 'Public Health Officer', 'Runs community health programmes, surveillance and health promotion for LGUs and health agencies. Not separately licensed, though most posts require an underlying health profession licence.', 28000, 90000, 'e0000002-0000-4000-8000-000000000002', 'SIE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('31758015-f6c4-5900-9380-d3480d47722a', 'Certified Public Accountant', 'Performs external auditing, public accounting and corporate financial reporting. Regulated under RA 9298: only BS Accountancy graduates may sit the CPA Licensure Examination, and the title may be used only after passing it, taking the oath and registering with the PRC Board of Accountancy.', 32000, 150000, 'e0000003-0000-4000-8000-000000000003', 'CEI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('dfc5b68b-1a5f-5af9-a6f2-40aa46b8c92d', 'Financial Analyst', 'Builds financial models, variance analysis and budgets for corporations, banks and BPO finance operations. Non-regulated; the CFA is an optional international credential rather than a legal requirement.', 32000, 120000, 'e0000003-0000-4000-8000-000000000003', 'CIE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('c3cbdf16-2b52-50bb-9c51-98f9732b1f85', 'Internal Auditor', 'Tests internal controls, compliance and process risk from inside the organisation. A non-licensure track — Certified Internal Auditor (CIA) certification rather than PRC registration.', 32000, 115000, 'e0000003-0000-4000-8000-000000000003', 'CIE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('38592889-30c0-5042-962d-3e8903737e70', 'Operations Manager', 'Runs supply chain, process and workforce performance across manufacturing, retail and logistics. Non-regulated; PMP and lean certifications are optional.', 42000, 150000, 'e0000003-0000-4000-8000-000000000003', 'ECS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('a8e6a1f8-519d-513d-bd36-305bf4ba33f7', 'Supply Chain Analyst', 'Plans inventory, demand and logistics flows, and measures where cost and delay accumulate. Non-regulated.', 28000, 95000, 'e0000003-0000-4000-8000-000000000003', 'CEI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('5a8a7ce7-f50c-523a-99b0-4cd86f0577a5', 'Marketing Specialist', 'Plans and runs campaigns, brand work and market research. Non-regulated.', 22000, 90000, 'e0000003-0000-4000-8000-000000000003', 'EAS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('63acaecd-8d41-52ae-b69c-e2c4f61d2c3d', 'Human Resources Specialist', 'Handles recruitment, job evaluation, organisational development and performance appraisal. Non-regulated; SHRM or CHRA certification is optional. A common destination for psychology graduates in Cebu corporate HR and BPO talent acquisition.', 22000, 85000, 'e0000003-0000-4000-8000-000000000003', 'SEC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('f1474f1e-2136-581d-9ffa-4703164845be', 'Office Administrator', 'Runs office systems, records, correspondence, scheduling and administrative support for a business unit or agency. Non-regulated; government appointments require Civil Service eligibility.', 14000, 35000, 'e0000002-0000-4000-8000-000000000002', 'CES', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('824bba56-c46f-5c5a-b1cd-ab207cdbe136', 'Executive Assistant', 'Manages the calendar, correspondence, records and travel of an executive or department, and coordinates across the units reporting to them. Non-regulated.', 16000, 45000, 'e0000002-0000-4000-8000-000000000002', 'CSE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('aeb22f28-4592-5854-b3c3-0f4cb6fb97d9', 'Bank Operations Officer', 'Runs branch and back-office banking operations, compliance checks and client accounts. Non-regulated, though BSP-supervised roles carry their own fit-and-proper requirements.', 22000, 80000, 'e0000002-0000-4000-8000-000000000002', 'CES', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('70a35d5b-6c47-5147-bc10-cf426563d014', 'Hotel Operations Manager', 'Runs rooms, food and beverage and events operations in hotels and resorts. Non-regulated. A substantial employer across Cebu, Mactan and Panglao.', 28000, 100000, 'e0000003-0000-4000-8000-000000000003', 'ESC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('beb9258f-606d-582e-93cf-7f965c1b10d6', 'Tourism Officer', 'Plans destination marketing, tour operations and visitor services for LGUs and travel operators. Non-regulated, though DOT accreditation applies to the establishments employing them.', 20000, 70000, 'e0000002-0000-4000-8000-000000000002', 'ESA', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('42bceab8-8681-5aef-9b52-1fba54e6abf9', 'Events Manager', 'Plans and runs weddings, conferences and corporate events end to end — suppliers, budget, programme and on-the-day operations. Non-regulated; a substantial market across Panglao and Tagbilaran.', 18000, 60000, 'e0000002-0000-4000-8000-000000000002', 'ESA', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('6c412f7c-5d04-5ad8-8a87-56fcf8557c2e', 'Food and Beverage Supervisor', 'Supervises restaurant, banquet and bar operations — service standards, costing, inventory and food safety compliance. Non-regulated, though kitchens operate under local sanitation permits.', 15000, 40000, 'e0000002-0000-4000-8000-000000000002', 'ECS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('16ede13d-79bf-51c5-8560-6cc11f868e6e', 'Tour Operations Manager', 'Builds and runs tour products and itineraries, manages guides and transport, and handles DOT accreditation for the operator. Non-regulated as a title; tour guiding itself requires DOT accreditation.', 18000, 55000, 'e0000002-0000-4000-8000-000000000002', 'ESC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('1a479c3c-1c02-5d2b-9844-9e0741ac95e1', 'Entrepreneur', 'Starts and runs a business, carrying its commercial and operational risk. Not a regulated profession; the constraints are capital, registration and the market.', 20000, 200000, 'e0000002-0000-4000-8000-000000000002', 'ECS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('31adf43f-4e20-57ae-8097-7910cf2e1d41', 'Elementary School Teacher', 'Teaches the K-6 curriculum in public and private elementary schools. Regulated under RA 7836 and RA 9293 — a BEEd degree grants eligibility, and teaching requires passing the Licensure Examination for Teachers and PRC registration.', 27000, 50000, 'e0000003-0000-4000-8000-000000000003', 'SAE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('5710969c-463f-5751-b441-d1a8c7e4db25', 'Secondary School Teacher', 'Teaches a subject specialisation in junior and senior high school. Regulated under RA 7836 and RA 9293 — a BSEd degree grants eligibility, and teaching requires passing the Licensure Examination for Teachers.', 27000, 55000, 'e0000003-0000-4000-8000-000000000003', 'SAE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('a1accb2a-7bc7-5a29-92d8-b5ec70291043', 'Physical Education Teacher', 'Teaches physical education and coaches school athletics programmes. Regulated under RA 7836 — a BPEd degree grants eligibility, and teaching requires passing the Licensure Examination for Teachers.', 27000, 48000, 'e0000003-0000-4000-8000-000000000003', 'SRE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('2ea491cb-f3ec-53e2-a824-2b16a0eaddfa', 'School Administrator', 'Leads a school or department — instructional supervision, staffing, compliance and DepEd reporting. A progression from teaching rather than an entry role: it requires the PRC teaching licence plus classroom experience, and public school principalship additionally requires the DepEd principals’ examination.', 35000, 80000, 'e0000002-0000-4000-8000-000000000002', 'SEC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('aabbdf60-dc69-5ddf-815a-40f08482085d', 'Athletic Coach', 'Trains and manages school, club or LGU athletic teams, including conditioning, competition entry and athlete development. Non-regulated; national sport associations run their own coaching accreditation.', 15000, 48000, 'e0000002-0000-4000-8000-000000000002', 'SER', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('ed6faf2d-19cd-55de-93d3-04972ef4d089', 'Psychometrician', 'Administers and scores standardised psychological tests and conducts behavioural observation in testing centres, schools and clinics. Regulated under RA 10029 — a BS or BA Psychology degree grants eligibility for the Psychometrician Licensure Examination. Practising as a Clinical Psychologist is a separate path requiring a Master’s degree and the Psychologist Licensure Examination.', 20000, 60000, 'e0000003-0000-4000-8000-000000000003', 'ISC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('23c478e1-4938-59c4-8823-dc64c0ac9299', 'Guidance Counselor', 'Provides academic, career and personal counselling in schools. Regulated under RA 9258 — requires a Master’s degree in guidance and counselling and the PRC Guidance Counselor Licensure Examination, so it is a graduate-level destination rather than a first job.', 26000, 70000, 'e0000002-0000-4000-8000-000000000002', 'SIA', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('5c92937b-0003-5497-9e28-7dedb4b21945', 'Registered Criminologist', 'Works in law enforcement, criminal investigation and correctional management. Regulated under RA 11131 — requires passing the PRC Criminologist Licensure Examination, and entry into the PNP additionally requires its own appointment and clearance process.', 29000, 70000, 'e0000003-0000-4000-8000-000000000003', 'RSE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('e1535232-73a3-5a2e-85e0-a700d3aba8f1', 'Crime Scene Investigator', 'Handles evidence recovery, latent fingerprint processing and forensic documentation for the NBI and the PNP Forensic Group. Requires the PRC Criminologist Licensure Examination under RA 11131.', 28000, 85000, 'e0000002-0000-4000-8000-000000000002', 'IRS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('64bc2652-ac9f-5034-914b-554aac13ff25', 'Fisheries Technologist', 'Runs fish hatchery operations, water quality analysis, feed formulation and aquatic pathology on commercial farms and for BFAR. Regulated under RA 8550 as amended by RA 10654 — practice requires passing the PRC Fisheries Technologist Licensure Examination.', 24000, 70000, 'e0000002-0000-4000-8000-000000000002', 'RIE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('addd65a2-0655-55e8-8bd6-228843388b4e', 'Agriculturist', 'Advises on crop and animal production, farm systems and extension work. Regulated under RA 8435 — practice as a professional agriculturist requires passing the PRC Agriculturist Licensure Examination.', 20000, 65000, 'e0000002-0000-4000-8000-000000000002', 'RIE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('cc1e8e3e-e978-511a-a9f0-6a7a12c5dddf', 'Food Technologist', 'Develops food products and runs processing, preservation, quality assurance and food-safety systems (HACCP, GMP) in manufacturing plants and for regulators. Regulated under RA 11052, the Philippine Food Technology Act — practice requires passing the PRC Food Technologist Licensure Examination and registering with the Board.', 18000, 50000, 'e0000002-0000-4000-8000-000000000002', 'IRC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('70b9c328-4b90-5dec-964a-8748027b8e77', 'Environmental Scientist', 'Assesses environmental impact and advises on remediation and compliance for industry and LGUs. Non-regulated as a profession, though environmental impact work is governed by DENR accreditation.', 28000, 85000, 'e0000003-0000-4000-8000-000000000003', 'IRS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('31b3f212-df30-5366-98b0-de7e8ab33adb', 'Pollution Control Officer', 'Runs a facility’s environmental compliance — effluent and emissions monitoring, waste manifests and the self-monitoring reports DENR requires. The role is mandatory for covered establishments and requires DENR-EMB accreditation as a PCO on top of the degree.', 22000, 65000, 'e0000003-0000-4000-8000-000000000003', 'IRC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('d22b2c5b-bf4a-52a3-aae3-b70ce8673b6e', 'Farm Operations Manager', 'Runs the production side of a commercial farm or aquaculture operation — cropping and stocking plans, labour, inputs, machinery and yield. Non-regulated, though signing off as a professional agriculturist requires the PRC licence.', 20000, 60000, 'e0000002-0000-4000-8000-000000000002', 'RES', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('e62e8344-5225-507b-a67a-38ff28691c71', 'Agricultural Extension Worker', 'Brings production technology and training to farmers and fisherfolk for LGU agriculture offices, DA and BFAR. Non-regulated; permanent government posts require Civil Service eligibility.', 18000, 45000, 'e0000002-0000-4000-8000-000000000002', 'RSI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('fe274ded-a698-5e98-ab2d-2f97c5c70c42', 'Marine Biologist', 'Studies marine organisms and ecosystems in field and laboratory settings — a substantial research area across the Visayan and Bohol Sea reef systems. Non-regulated.', 24000, 70000, 'e0000002-0000-4000-8000-000000000002', 'IRA', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('690db7b0-a009-5196-9e37-39073e9d0429', 'Laboratory Research Associate', 'Runs experiments, sample preparation and instrumentation in academic and industrial laboratories. Non-regulated at associate level.', 20000, 65000, 'e0000002-0000-4000-8000-000000000002', 'ICR', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('5562a94f-c12a-5d93-8162-9ae0c57fd417', 'Multimedia Artist', 'Produces animation, motion graphics and digital media for studios and agencies. Non-regulated; hired on portfolio.', 20000, 80000, 'e0000003-0000-4000-8000-000000000003', 'AIR', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('cdb1ea89-4df2-51f5-8eda-b45fa8d0d07e', 'Graphic Designer', 'Designs visual communication across print and digital media. Non-regulated; hired on portfolio.', 18000, 70000, 'e0000002-0000-4000-8000-000000000002', 'ARE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('a5a3c1fd-dade-5937-9cca-25370d2d3df3', 'Communications Officer', 'Runs corporate and public communications — media relations, content and internal communication. Non-regulated.', 22000, 80000, 'e0000002-0000-4000-8000-000000000002', 'AES', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('874892a1-4e1d-5a4f-af9e-ff3a1e54c325', 'Content Writer and Editor', 'Writes and edits copy for publications, marketing teams, agencies and technical documentation. Non-regulated; hired on portfolio.', 18000, 65000, 'e0000002-0000-4000-8000-000000000002', 'AIC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('21a9948c-84e7-5d74-923a-e15dbd6d117f', 'Journalist', 'Reports, writes and produces news for broadcast, print and digital outlets. Non-regulated.', 18000, 70000, 'e0000002-0000-4000-8000-000000000002', 'AIS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('b5aa6fdf-2cbe-5f10-a09f-eca2494cf5d8', 'Lawyer', 'Advises clients, drafts instruments and represents parties before the courts and quasi-judicial agencies. Entered through the Juris Doctor, which is a graduate-entry degree, and admission to practice requires passing the Philippine Bar Examination and being admitted to the Roll of Attorneys — the Bar is administered by the Supreme Court, not the PRC.', 40000, 180000, 'e0000002-0000-4000-8000-000000000002', 'EIS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('11e83c52-c882-5cfc-8e99-edace4db44e5', 'Policy Research Analyst', 'Researches and drafts policy positions, legislative briefs and programme evaluations for LGUs, national agencies, legislators and NGOs. Non-regulated; permanent government posts require Civil Service eligibility.', 25000, 75000, 'e0000002-0000-4000-8000-000000000002', 'IES', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('adf23186-7acf-5876-819b-89ea93d471ce', 'Legal Researcher', 'Researches jurisprudence and statutes, drafts pleadings and memoranda and manages case records for law firms, courts and corporate legal units. Non-regulated and open before admission to the Bar — it is the common working role for a law student or an unadmitted graduate.', 20000, 55000, 'e0000002-0000-4000-8000-000000000002', 'ICE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('ef72c3cf-6f90-5954-b7cb-4fc5309c2375', 'Security Operations Manager', 'Runs guard force operations, access control, investigations and loss prevention for an establishment or a security agency. Governed by RA 11917: agency operators and security professionals require PNP-SOSIA licensing.', 20000, 65000, 'e0000002-0000-4000-8000-000000000002', 'ERC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('1c4a59e2-b15b-594d-b9a1-ef2dbed39c06', 'Fire Officer', 'Fire suppression, rescue and fire safety inspection with the Bureau of Fire Protection. Entry is by BFP appointment under RA 9263 and requires either a relevant baccalaureate or a PRC/CSC eligibility, plus the BFP’s own recruitment and training process.', 25000, 50000, 'e0000002-0000-4000-8000-000000000002', 'RSE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('afc9cfc9-156f-504e-9929-ad49b8e900d6', 'Public Administration Officer', 'Works in policy, legislative research and programme administration in national agencies and LGUs. Non-regulated, though career service eligibility (CSC) applies to permanent government appointments.', 25000, 90000, 'e0000002-0000-4000-8000-000000000002', 'ESC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('9bd6f94d-3450-5667-8203-e9d9cd5e22de', 'Tax Advisory Specialist', 'Advises on corporate taxation, tax filing and BIR compliance for consultancies and corporate tax units. Requires the same CPA licence as external audit under RA 9298 — a BS Accountancy degree, the CPALE, and PRC registration.', 30000, 120000, 'e0000003-0000-4000-8000-000000000003', 'CIS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('851fbeb6-a6d2-51c2-b44c-be7a249a61a1', 'Chief Financial Officer', 'Owns capital structure, enterprise risk and strategic finance for a company. Not an entry-level role: normally a CPA licence plus roughly eight years of progressive finance experience.', 90000, 400000, 'e0000002-0000-4000-8000-000000000002', 'ECI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('356cb085-ab5f-5274-8e13-00fdbf394e8a', 'Business Development Specialist', 'Builds partnerships, market research and growth plans for corporate strategy units and startups. Non-regulated.', 28000, 110000, 'e0000003-0000-4000-8000-000000000003', 'ESI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('6ba3e1ba-f3a0-58ae-9724-839811178c2b', 'AI/Machine Learning Engineer', 'Builds and deploys deep learning, computer vision and natural language systems for R&D labs and technology startups. Non-regulated; TensorFlow and PyTorch certifications are the usual signal.', 50000, 180000, 'e0000004-0000-4000-8000-000000000004', 'IRC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('415b62b2-3566-5480-b0f5-e1a5940e7906', 'Enterprise Systems Architect', 'Designs system scalability, cloud infrastructure and API strategy across an organisation. Not an entry-level role: normally five or more years of software development first. Non-regulated.', 70000, 220000, 'e0000002-0000-4000-8000-000000000002', 'IEC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('6b413164-26c6-589d-b0fe-8965d351de89', 'Urban and Regional Planner', 'Handles spatial analysis, zoning governance and environmental impact assessment for LGU planning offices and NEDA. Regulated under RA 10587 — requires postgraduate planning study and the PRC Environmental Planner licence, on top of an architecture or engineering degree.', 40000, 130000, 'e0000002-0000-4000-8000-000000000002', 'IES', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('7741aefa-f176-5469-ba76-557a87fcbd48', 'BIM Specialist', 'Produces 3D structural models, parametric design and clash analysis for engineering and design consultancies. Non-regulated; Autodesk Revit certification is the usual credential.', 30000, 100000, 'e0000003-0000-4000-8000-000000000003', 'RIA', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('eee893bd-2066-570c-866e-82d84c6e1917', 'CAD Design Technician', 'Produces 2D and 3D computer-aided drafting, blueprint reading and rendering for construction firms and architectural studios. Non-regulated; AutoCAD or SolidWorks certification and a TESDA National Certificate are the usual credentials.', 18000, 60000, 'e0000002-0000-4000-8000-000000000002', 'RCA', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));

INSERT OR IGNORE INTO careers (id, title, description, salary_min, salary_max, employment_outlook_id, typical_riasec_code, status, created_at, updated_at) VALUES
('139d52c5-5872-51d2-8355-71b7a9467e13', 'Geotechnical Engineer', 'Works on soil mechanics, slope stability, foundation design and drilling logs for foundation engineering consultancies. Regulated under RA 544 — requires the PRC Civil Engineering Licensure Examination.', 32000, 120000, 'e0000002-0000-4000-8000-000000000002', 'RIC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('d35009da-659b-5945-9f6d-94ac18156b69', 'HVAC Design Engineer', 'Designs heating and ventilation systems, psychrometric calculation and duct sizing for MEP consultancies and construction. Regulated under RA 8495 — requires the PRC Mechanical Engineer Licensure Examination.', 32000, 120000, 'e0000003-0000-4000-8000-000000000003', 'RIE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('ddff8b21-3cbb-5b42-aa12-6eb1afbcd81c', 'Power Plant Engineer', 'Runs turbine maintenance, boiler operation and thermal efficiency monitoring at power generation facilities and utilities. Requires a PRC mechanical or electrical engineering licence depending on the plant systems supervised.', 35000, 130000, 'e0000002-0000-4000-8000-000000000002', 'RCI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('3d4a171f-642f-57a5-a317-e42a13e357ca', 'Public Health Nurse', 'Runs community health assessment, immunisation programmes and health education for the DOH and rural health units. Requires the same RN licence as hospital nursing under RA 9173 — the Nurse Licensure Examination and PRC registration.', 22000, 60000, 'e0000003-0000-4000-8000-000000000003', 'SIC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('4bc743f2-ccd6-5601-83d3-74e0e50d74ac', 'Nurse Administrator', 'Manages wards, healthcare quality assurance and nursing staff governance. Not an entry-level role: an RN licence plus a Master of Science in Nursing is the normal requirement.', 45000, 140000, 'e0000002-0000-4000-8000-000000000002', 'SEC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('d4583f0a-1bb9-50e0-8d0a-770b2bf6a004', 'Clinical Psychologist', 'Carries out psychological diagnosis, psychotherapy and clinical assessment. Regulated under RA 10029 and **not** reachable on a bachelor’s degree alone: it requires a Master’s degree in psychology and the Psychologist Licensure Examination, which is a different examination from the Psychometrician one.', 40000, 150000, 'e0000002-0000-4000-8000-000000000002', 'ISA', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('1a4304e0-73bd-51ef-8f57-3de5342e24b4', 'Deck Officer', 'Stands navigation watch and manages cargo operations on commercial vessels. Credentialled under the STCW Convention and RA 10635 by MARINA, not the PRC: a BS Marine Transportation degree, twelve months of approved seagoing service and assessment, then a Certificate of Competency as Officer in Charge of a Navigational Watch.', 60000, 250000, 'e0000003-0000-4000-8000-000000000003', 'RCI', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('ae935b7f-33ff-55b1-be39-11cbfbfcd08c', 'Marine Surveyor', 'Inspects hulls, evaluates cargo damage and audits maritime safety compliance for classification societies and cargo inspectors. Requires MARINA certification and prior sea experience.', 40000, 140000, 'e0000002-0000-4000-8000-000000000002', 'RCE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('89627f26-fa5a-5ebc-af86-3902bc624a80', 'Port Operations Supervisor', 'Coordinates vessel berthing, container terminal operations and port safety for port authorities and terminal operators. Non-regulated; port safety certification is optional.', 30000, 100000, 'e0000003-0000-4000-8000-000000000003', 'ECR', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('6fcf4897-3fa0-50e8-8f0c-40a06a4bbf9d', 'Ship Captain', 'Commands a vessel, its safety management and maritime law compliance. The top of the deck career, not an entry point: a Master Mariner licence built on roughly ten years of sea time.', 150000, 500000, 'e0000002-0000-4000-8000-000000000002', 'REC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('d720544f-8010-590d-b39d-4f5e5542be5d', 'Police Officer', 'Carries out criminal investigation, patrol operations and arrest procedures in the Philippine National Police. Requires the PRC Criminologist Licensure Examination under RA 11131 *and* separate PNP appointment eligibility — passing the board alone does not confer a police appointment.', 29000, 75000, 'e0000003-0000-4000-8000-000000000003', 'RSE', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('16fb352d-672a-54f4-b1a9-4383537aa7c4', 'Correctional Officer', 'Handles inmate custody, prison security management and rehabilitation programmes for the Bureau of Corrections and BJMP. Requires the PRC Criminologist Licensure Examination under RA 11131.', 29000, 65000, 'e0000002-0000-4000-8000-000000000002', 'RSC', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('828293ec-5d3a-5798-9ad4-2e4a00945d3f', 'Curriculum Developer', 'Designs instruction, maps learning outcomes and edits textbooks for educational publishers and EdTech firms. Non-regulated, though a teaching licence and a Master of Arts in Education are common.', 25000, 85000, 'e0000002-0000-4000-8000-000000000002', 'AIS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('ad6e36c6-dc81-57c3-aa83-9e40d0519bd3', 'Aquatic Resource Specialist', 'Works on coastal resource management, fish stock assessment and biodiversity protection for coastal LGUs and marine NGOs. Requires the PRC Fisheries Technologist licence under RA 8550 as amended.', 24000, 75000, 'e0000002-0000-4000-8000-000000000002', 'IRS', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));

-- --- Canonical programmes (41) ------------------------------------------------------
--
-- "BS Computer Science" as a thing in the world, of which each `programs` row below is one
-- institution's offering. This is what makes "which colleges offer this programme?" a join
-- rather than a string match (migration 0018).
--
-- Normalisation here follows one rule: **collapse titles, preserve scope of practice.** BSCS,
-- BSIT, BSIS and BSCpE stay four separate entries because they are four different careers, and
-- BSA stays separate from BSMA and BS AIS because only BSA graduates may sit the CPALE under
-- RA 9298. What *does* collapse is a single curriculum under two names — "BS Medical
-- Technology" and "BS Medical Laboratory Science" are one programme sitting one licensure exam,
-- so they are one canonical entry with the institution's own title kept on its offering row.

INSERT OR IGNORE INTO program_catalog (id, code, name, description, recommended_strand, status, created_at, updated_at) VALUES
('b3a34062-d287-51ba-ba69-912a32288737', 'BSCS', 'BS Computer Science', 'Computational theory, algorithm design and software architecture.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('3503ebfe-b102-5a6e-9e11-e269bff6f3e3', 'BSIT', 'BS Information Technology', 'Systems administration, network infrastructure and web application deployment.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('baba3166-1d88-5b53-a97b-20e46af2cd35', 'BSIS', 'BS Information Systems', 'Business process integration and enterprise software systems.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('83c3a217-2e32-5b23-9a48-3da054e3e29f', 'BSCPE', 'BS Computer Engineering', 'Hardware-software interfaces, embedded circuit design and computer architecture.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('a7162be6-26ea-5d74-b3c4-5a6728db50e6', 'BSCE', 'BS Civil Engineering', 'Structural calculation, reinforced concrete design, hydraulics and construction cost estimation.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('3d9b2fca-775a-50fe-8d16-3441cb4f6128', 'BSME', 'BS Mechanical Engineering', 'Thermodynamics, machine design and manufacturing systems.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('7c1b02f3-70c0-589c-80db-896dda916cd3', 'BSEE', 'BS Electrical Engineering', 'Power systems, electrical machines and building electrical design.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('c8361864-4fe8-54ba-bf7f-5a497eadbe45', 'BSABE', 'BS Agricultural and Biosystems Engineering', 'Farm machinery, irrigation and land-and-water resources engineering, and agricultural processing plant.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('edb87f27-ef42-5011-842f-f2fad7890eea', 'BSARCH', 'BS Architecture', 'Architectural design, building code compliance, AutoCAD and Revit (BIM) practice.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('283d712a-b9a8-51f5-8a70-0d13b95fc317', 'BSINDDES', 'BS Industrial Design', 'Product design, materials and manufacture, prototyping and human factors. Distinct from interior design and from industrial engineering: the object is the artefact.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('b746b1e6-71a5-5364-a8c1-a5468caa30aa', 'BSMARE', 'BS Marine Engineering', 'Shipboard machinery, propulsion and marine systems, with supervised sea service.', 'Technical-Professional', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('a43c62b2-7130-5c2b-ae10-1090de308701', 'BSMARTRANS', 'BS Marine Transportation', 'Ocean navigation, watchkeeping, passage planning, cargo operations and collision regulations.', 'Technical-Professional', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('b9148ea2-5533-536f-a8e3-8b5a5dc64c08', 'BSINDTECH', 'BS Industrial Technology', 'Applied manufacturing, machine shop, welding and industrial maintenance practice.', 'Technical-Professional', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('c8d52465-fc72-56d6-9321-da4e9069edc4', 'BSELECTECH', 'BS Electrical Technology', 'Electrical installation, motor control and building wiring to Philippine Electrical Code practice.', 'Technical-Professional', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('c0fee9d7-d8ba-53a4-907d-31ea2f97bb87', 'BSELXTECH', 'BS Electronics Technology', 'Electronic servicing, instrumentation and communications equipment maintenance.', 'Technical-Professional', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('f00c131f-46ee-56c6-b911-709b05ef167f', 'BSN', 'BS Nursing', 'Clinical patient care, IV therapy, bedside assessment and emergency response.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('e18faef7-3bd9-5f94-ace2-b36e226f46d5', 'BSPHARM', 'BS Pharmacy', 'Pharmaceutical science, dispensing and pharmacy practice.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('4687f217-2a4e-54c1-b719-593a05631b34', 'BSPT', 'BS Physical Therapy', 'Rehabilitation of movement and physical function.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('ab91b6c2-f9ed-57c5-8884-b3cdbfb0b99f', 'BSMID', 'BS Midwifery', 'Prenatal, delivery and postnatal care, newborn care and maternal health in community and facility settings.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('d4a2348a-76de-5f7d-a4c9-bab0cff88d65', 'BSA', 'BS Accountancy', 'Financial auditing, PFRS/IAS standards, internal controls and tax compliance. The only accounting track whose graduates may sit the CPA Licensure Examination.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('cb851372-136c-58df-a569-6aa712165178', 'BSAIS', 'BS Accounting Information Systems', 'Accounting systems, controls and business process automation. A non-licensure track.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('3488d939-5b20-5ad9-8f89-2cc29279f86f', 'BSBA', 'BS Business Administration', 'Management, marketing, finance and operations.', 'Academic', 'active', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
